  "O modelu i źródłach": "About the model and sources",
  "Model przedstawia anatomię mężczyzny. To atlas edukacyjny z oddzielnymi mięśniami i szkieletem, a nie fotograficzna rekonstrukcja obrazu. Tryb „Głębokie” odsłania głębsze struktury przez wyłączenie mięśni powierzchownych. Nie wszystkie mięśnie głębokie pełnią wyłącznie funkcję stabilizacyjną.": "The model shows male anatomy. This is an educational atlas with separate muscles and a skeleton, rather than a photographic reconstruction. Deep mode reveals deeper structures by hiding superficial muscles. Some deep muscles also have functions beyond stabilisation.",
  ", autorzy: Kousaku Okubo / DBCLS (BodyParts3D), Gauthier Kervyn i współtwórcy Z-Anatomy. Źródłowe BodyParts3D: CC BY-SA 2.1 Japan; Z-Anatomy i osadzone opracowanie geometrii:": ", authors: Kousaku Okubo / DBCLS (BodyParts3D), Gauthier Kervyn and the Z-Anatomy contributors. Original BodyParts3D: CC BY-SA 2.1 Japan; Z-Anatomy and the embedded geometry adaptation:",
  ". Zmiany w tym pliku: wybór struktur, uproszczenie siatek, grupowanie, kompresja, materiały i polski interfejs. Włóknista faktura jest efektem graficznym.": ". Changes in this file: structure selection, mesh simplification, grouping, compression, materials and a Polish interface. The fibrous texture is a visual effect.",
  "OpenStax, Anatomy and Physiology 2e, rozdział 11": "OpenStax, Anatomy and Physiology 2e, Chapter 11",
  ". Ćwiczenia to przykłady angażujące dane mięśnie, nie instrukcje ich izolowania. Silnik: Three.js (MIT); dekompresja: fflate (MIT).": ". These exercises are examples that engage the muscles, rather than instructions for isolating them. Engine: Three.js (MIT); decompression: fflate (MIT).",
  "Model anatomiczny 3D. Przeciągnij, aby obracać. Kliknij mięsień, aby zobaczyć opis. Strzałki obracają, plus i minus zmieniają powiększenie.": "3D anatomical model. Drag to rotate. Click a muscle to see its description. Arrow keys rotate; plus and minus change the zoom.",
  "Nie można wyświetlić modelu 3D": "Cannot display the 3D model",
  "Ta przeglądarka nie uruchomiła grafiki WebGL. Otwórz zapisany plik HTML w aktualnej przeglądarce z obsługą WebGL. Lista mięśni i opisy poniżej są nadal dostępne.": "This browser could not start WebGL graphics. Open the saved HTML file in a current browser with WebGL support. The muscle list and descriptions below are still available.",
