  "Zaznaczenie z listy obejmuje obie strony. Kliknięcie modelu wybiera wskazaną stronę. Przykłady ćwiczeń mogą angażować również inne mięśnie.": "Selecting from the list includes both sides. Clicking the model selects the indicated side. The example exercises may also involve other muscles.",
