  "Jeszcze nieukończone": "Not yet completed",
  "Jeżeli nie przerabiałeś wcześniej pytań z tego zakresu, domyślna pula jest pusta. Otwórz listę i włącz wybrane pytania albo całą pulę.": "If you have not studied questions from this area before, the default pool is empty. Open the list and enable selected questions or the entire pool.",
