  "Limit czasu: 1 minuta na pytanie. Tryb nauki nie ma limitu czasu ani blokady dostępu.": "Time limit: 1 minute per question. Study mode has no time limit or access restriction.",
  "Losowa fiszka": "Random flashcard",
  "Losowe pytania ze wszystkich podsekcji tej części. Pytania wyłączone w podsekcjach są automatycznie pomijane.": "Random questions from all subsections in this part. Questions disabled in subsections are skipped automatically.",
  "Mapa nauki": "Study map",
  "Możesz podejść do egzaminu końcowego": "You can take the final exam",
  "Możesz przejść do egzaminu zaliczeniowego z progiem 80%, jeśli notatka również została przeczytana.": "You can take the qualifying exam with an 80% pass mark if you have also read the note.",
  "Możesz rozpocząć podejście.": "You can start this attempt.",
  "Możesz spróbować ponownie od razu.": "You can try again immediately.",
  "Możesz włączyć pytania, których jeszcze nie przerabiałeś. „Włącz wszystkie” pomija konieczność wcześniejszego przechodzenia testów. „Wyłącz wszystkie” opróżnia bieżącą pulę bez kasowania pytań z aplikacji.": "You can enable questions you have not yet studied. “Enable all” removes the need to complete tests first. “Disable all” empties the current pool without deleting questions from the app.",
  "Na dziś nie ma aktywnych fiszek w tej podsekcji. Wyłączone pytania nadal pojawią się w egzaminie zaliczeniowym.": "There are no active flashcards for today in this subsection. Disabled questions will still appear in the qualifying exam.",
  "Na przodzie fiszki widzisz termin łaciński. Po odsłonięciu pojawia się jego polskie tłumaczenie.": "The front of the flashcard shows the Latin term. Reveal the back to see its Polish translation.",
  "Na teraz wszystko powtórzone": "All reviews completed for now",
