  "Najpierw zalicz": "Pass first",
  "Najpierw zalicz podsekcje": "Pass the subsections first",
  "Następna →": "Next →",
  "Nauka prawa w uporządkowanej aplikacji: przedmioty, notatki, pytania, fiszki i egzaminy.": "Structured law study: subjects, notes, questions, flashcards and exams.",
  "Nauki prawne": "Legal studies",
  "Nauki prawne — rekomendowana kolejność nauki": "Legal studies — Recommended study order",
  "Nie można przejść do następnego pytania bez zaznaczenia odpowiedzi. Limit czasu: 1 minuta na pytanie. Pytania w jednym podejściu nie są dublowane. Tryb nauki działa bez limitu czasu i niezależnie od blokady egzaminu.": "Select an answer before moving to the next question. Time limit: 1 minute per question. Questions do not repeat within an attempt. Study mode has no time limit and is available even when the exam is locked.",
  "Nie trafia do zwykłej nauki ani fiszek; pozostaje w egzaminach zaliczeniowych": "Excluded from regular study and flashcards; still included in qualifying exams",
  "Nie zaliczono egzaminu sekcji.": "Section exam not passed.",
  "Nie zaliczono egzaminu z łaciny.": "Latin exam not passed.",
  "Nie zaliczono.": "Not passed.",
  "Nie znam": "Don't know",
  "Nie znam → po 1 innej fiszce • Słabo → po 4 innych fiszkach • Dobrze → jutro • Bardzo dobrze → za 3 dni. Drugie kolejne „Bardzo dobrze” wyłącza hasło jako opanowane.": "Don't know → after 1 other flashcard • Weak → after 4 other flashcards • Good → tomorrow • Very good → in 3 days. A second consecutive “Very good” disables the entry as mastered.",
  "Nie znam → po 1 innej fiszce • Słabo → po 4 innych fiszkach • Dobrze → jutro • Bardzo dobrze → za 3 dni. Drugie kolejne „Bardzo dobrze” wyłącza pytanie jako opanowane.": "Don't know → after 1 other flashcard • Weak → after 4 other flashcards • Good → tomorrow • Very good → in 3 days. A second consecutive “Very good” disables the question as mastered.",
  "Nie znam → po 1 innej fiszce • Słabo → po 4 innych fiszkach • Dobrze → jutro • Bardzo dobrze → za 3 dni. Drugie kolejne „Bardzo dobrze” wyłącza pytanie jako opanowane. Możesz je ponownie włączyć w zakładce „Pytania”.": "Don't know → after 1 other flashcard • Weak → after 4 other flashcards • Good → tomorrow • Very good → in 3 days. A second consecutive “Very good” disables the question as mastered. You can enable it again in the “Questions” tab.",
  "Niepoprawna odpowiedź — pytanie trafia na koniec kolejki.": "Incorrect answer — the question moves to the end of the queue.",
