  "Pełna pula:": "Full pool:",
  "Pełna ścieżka ukończona: próg zaliczenia wynosi 80% i po niezdanym egzaminie możesz próbować ponownie od razu.": "Full pathway completed: the pass mark is 80%, and you can try again immediately after a failed exam.",
  "Po zbudowaniu bazy wybierasz docelową aplikację. Każda otwiera osobną część zawodową z warsztatem, pismami, kazusami, etyką i przygotowaniem egzaminacyjnym.": "After building your foundation, choose your intended legal traineeship. Each opens a separate professional section with practical skills, legal documents, case studies, ethics and exam preparation.",
  "Pobierz certyfikat PNG": "Download PNG certificate",
  "Podejdź do egzaminu sekcji": "Take the section exam",
