  "Pokaż tłumaczenie": "Show translation",
  "Pomijasz co najmniej jeden wcześniejszy etap: próg zaliczenia wynosi 90%. Niezdane podejście skróconą ścieżką blokuje kolejną próbę na 2 godziny.": "You are skipping at least one earlier stage: the pass mark is 90%. A failed attempt using the shortened pathway locks the next attempt for 2 hours.",
