  "Rozdział": "Chapter",
  "Rozdział / część": "Chapter / part",
  "Rysunkowe drzewo nauk prawnych z odgałęzieniami prowadzącymi do aplikacji radcowskiej, adwokackiej, sędziowskiej, prokuratorskiej, notarialnej i komorniczej oraz do głównej ścieżki Nauki prawne.": "An illustrated legal study tree with branches leading to legal adviser, advocate, judicial, prosecutorial, notarial and enforcement officer traineeships, and the main Legal studies pathway.",
