  "Stan pytań i fiszek": "Question and flashcard status",
  "Stronicowanie listy pytań": "Question list pagination",
  "Szara": "Grey",
  "Słabo": "Weak",
  "Ta część jest celowo oddzielona od kursów akademickich. Zwykłe przedmioty dają wiedzę bazową, a tutaj ćwiczysz wyłącznie zastosowanie zawodowe.": "This section is separate from the academic courses. The subjects provide foundational knowledge; here you practise its professional application.",
  "Ta część obejmuje jeden rozdział, dlatego jego sekcje pokazujemy od razu — bez dodatkowego, pustego poziomu nawigacji.": "This part contains one chapter, so its sections are shown directly.",
  "Ta podsekcja nie ma jeszcze pytań potrzebnych do egzaminu zaliczeniowego.": "This subsection does not yet have the questions needed for a qualifying exam.",
  "Ten egzamin jest częścią warunku ukończenia głównego kursu Łacińska terminologia prawnicza.": "Passing this exam is required to complete the main Latin Legal Terminology course.",
  "Ten zakres nie ma jeszcze pytań, z których można utworzyć parę: jedna odpowiedź poprawna i jedna błędna.": "This area does not yet have questions that can form a pair with one correct and one incorrect answer.",
  "Terminy:": "Review dates:",
  "Test próbny": "Practice test",
  "Test próbny korzysta wyłącznie z aktywnych pytań i nie wpływa na zaliczenie podsekcji. Aktualna aktywna pula:": "The practice test uses only active questions and does not affect subsection completion. Current active pool:",
  "To dynamiczny indeks terminów z innych kursów. Każde hasło pozostaje również w sekcji „Łacina” swojego działu źródłowego.": "This is a dynamic index of terms from other courses. Each entry also remains in the “Latin” section of its original course.",
  "Traktuj ją jako główną kolejność nauki. Nie musisz kończyć jednego przedmiotu w 100% przed rozpoczęciem kolejnego, ale wcześniejsze bloki powinny być już dobrze opanowane.": "Use this as your main study order. You can start a new subject before completing the previous one, provided you have a good grasp of the earlier material.",
  "Tryb nauki łaciny": "Latin study mode",
  "Tryb nauki — bez blokady": "Study mode — Unrestricted access",
  "Tryb nauki — cała sekcja": "Study mode — Entire section",
  "Tryb nauki — łacina": "Study mode — Latin",
  "Tylko pytania błędne w testach albo ocenione „Nie znam/Słabo” więcej niż 5 razy. Pula pytań uznanych ponownie za łatwe jest automatycznie pomijana.": "Only questions answered incorrectly in tests or rated “Don't know/Weak” more than 5 times. Questions rated easy again are skipped automatically.",
