  "łacina": "Latin",
  "Ścieżka porządkuje naukę od fundamentów i języka prawa, przez podstawowe gałęzie, aż do specjalizacji i przygotowania pod konkretną aplikację.": "This pathway organises your studies from the foundations and language of law, through its main branches, to specialisation and preparation for a particular legal traineeship.",
  "Ścieżka zaliczenia: podsekcje → egzamin sekcji → egzaminy rozdziału → egzaminy części → zestaw egzaminów końcowych.": "Assessment pathway: subsections → section exam → chapter exams → part exams → final exams.",
