  "— oznaczenie dotyczy tylko wybranych pytań: absolutnych podstaw oraz zagadnień realnie często sprawdzanych na egzaminach lub istotnych w przygotowaniu do aplikacji.": "— this label applies only to selected questions: essential foundations and topics frequently tested in exams or important for legal traineeship preparation.",
