  "Nie udało się wczytać laboratorium. Sprawdź połączenie i spróbuj ponownie.": "Could not load the lab. Check your connection and try again.",
  "Wczytywanie laboratorium sieciowego…": "Loading the network lab…",
  "To laboratorium jest dostępne po zalogowaniu.": "Sign in to access this lab.",
  "Nie znaleziono scenariusza tego tematu.": "No scenario was found for this topic.",
  "Wykonaj laboratorium w przeglądarce": "Complete the lab in your browser",
  "Otwórz ćwiczenie tego tematu: konfiguruj urządzenia, korzystaj z CLI i obserwuj pakiety. Każdy temat ma osobny zapis. Wspólny katalog i narzędzia są dostępne w całym kursie.": "Open this topic's exercise: configure devices, use the CLI and observe packets. Each topic has its own saved state. The shared catalogue and tools are available throughout the course.",
  "Otwórz laboratorium sieciowe": "Open network lab",
  "Otwórz laboratorium": "Open lab",
  "WLC jest wyłączony. Włącz zasilanie w zakładce Physical.": "The WLC is powered off. Turn on its power in the Physical tab.",
  "Menu kontrolera": "Controller menu",
  "W trybie local switching DHCP i ruch klientów przechodzą przez VLAN na porcie AP. Adres interfejsu WLC opisuje przypisanie sieci; WLC nie jest bramą routującą klientów.": "In local switching mode, DHCP and client traffic pass through the VLAN on the AP port. The WLC interface address identifies the network assignment; the WLC does not act as a routing gateway for clients.",
  "AP dołącza po osiągnięciu adresu zarządzania kontrolera przez UDP 5246. Sprawdź IP, VLAN zarządzania, routing i ACL.": "The AP joins when it can reach the controller's management address over UDP 5246. Check the IP address, management VLAN, routing and ACLs.",
  "Skojarzenie radiowe i łączność IP sprawdzaj osobno. Poprawny klucz nie zastępuje VLAN-u ani adresacji.": "Check wireless association and IP connectivity separately. A correct key does not replace VLAN and addressing configuration.",
  "Zacznij od": "Start with",
  ", następnie utwórz i włącz profil w": ", then create and enable a profile in",
  ". Zakładki Wireless i Clients pokazują bieżący stan.": ". The Wireless and Clients tabs show the current state.",
  "Zastosuj i dołącz do WLC": "Apply and join the WLC",
  "Profile z kontrolera": "Profiles from the controller",
  "SSID i zabezpieczenia ustaw w GUI kontrolera. Port switcha do AP musi przenosić VLAN zarządzania oraz VLAN-y klientów.": "Set the SSID and security in the controller GUI. The switch port connected to the AP must carry the management VLAN and client VLANs.",
  "50 działów, 127 tematów i 5 dodatkowych ćwiczeń: OSPF DR/BDR, DHCP relay, pule NAT, IPv6 SLAAC oraz WLC. Każdy temat i wariant ma własny zapis; wszystkie udostępniają wspólny katalog i silnik.": "50 sections, 127 topics and 5 additional exercises: OSPF DR/BDR, DHCP relay, NAT pools, IPv6 SLAAC and WLC. Each topic and variant has its own saved state; all share the same catalogue and engine.",
  "Każdy temat udostępnia cały katalog i wspólne funkcje silnika. Pomoc kontekstowa CLI: ?, skróty jednoznaczne, Tab, do, Ctrl+Z. Narzędzia zawierają inwentarz, REST API i konfigurację zbiorczą.": "Every topic provides the full catalogue and shared engine features. CLI context-sensitive help: ?, unambiguous abbreviations, Tab, do and Ctrl+Z. Tools include inventory, a REST API and bulk configuration.",
