  ". Auto MDI-X jest domyślnie włączone, więc oba przewody miedziane mogą zestawić łącze na 2960.": ". Auto MDI-X is enabled by default, so either copper cable type can establish a link on a 2960.",
  ". Koperta i lista zdarzeń pokazują aktualnie obsługiwaną ramkę; kliknij zdarzenie, aby otworzyć pola PDU.": ". The envelope and event list show the frame currently being processed; click an event to open the PDU fields.",
  ". Maska wszędzie:": ". Subnet mask throughout:",
  ". Na obu przełącznikach otwórz CLI i wykonaj poniższe polecenia. Najpierw odczytaj cztery MAC, potem wyczyść i ponownie sprawdź pustą tablicę.": ". Open the CLI on both switches and run the commands below. First read the four MAC addresses, then clear the table and check that it is empty.",
